import re,glob,json,os,statistics as st
L=open('logs/practice-v9-team.log').read()
new={}
for m in re.finditer(r"^(case:P\d+) (.*)$", L, re.M):
    cid, rest = m.group(1), m.group(2)
    if rest.startswith('{'):
        sc=re.search(r"'score': ([\d.e-]+)", rest); new[cid]=(float(sc.group(1)) if sc else None, re.search(r"'unit_price': ([\d.]+)", rest).group(1) if 'unit_price' in rest else None, 'deal' if "'deal': True" in rest else 'NO DEAL')
    elif cid not in new and not rest.startswith(('sup:','research',"{'t'",'None')): new[cid]=(None, rest[:90], 'ERR')
print(re.findall(r"mean score.*|practice sessions left.*", L))
best={"P08":0.6704,"P05":0.8280,"P10":0.6785,"P02":0.7347,"P07":0.7510,"P04":0.8604,"P11":0.7099,"P18":0.6295,"P01":0.9739,"P03":0.9228}
# plain engine history from logs/runs before today 22:00 (latest and mean per case)
hist={}
for f in sorted(glob.glob('logs/runs/P*.json'), key=os.path.getmtime):
    d=json.load(open(f)); 
    if any(n['what']=='research' or n['what']=='analyst' for n in d['notes']): continue
    s=d['result'].get('score'); 
    if s is not None: hist.setdefault(d['case'].split(':')[1],[]).append(s)
print(f"{'case':5} {'team':>6} {'best':>6} {'plain last':>10} {'plain mean':>10}  price")
rows=[]
for c in sorted(best):
    s=new.get('case:'+c,(None,None,'missing'))
    h=hist.get(c,[])
    rows.append((s[0],best[c],h[-1] if h else None))
    print(f"{c:5} {s[0] if s[0] is None else round(s[0],3)!s:>6} {best[c]:6.3f} {round(h[-1],3) if h else '-':>10} {round(st.mean(h),3) if h else '-':>10}  {s[1]} {s[2]}")
ok=[r for r in rows if r[0] is not None]
print('n',len(ok),'team mean',round(st.mean(r[0] for r in ok),4),'best mean',round(st.mean(r[1] for r in ok),4),'plain-last mean',round(st.mean(r[2] for r in ok if r[2] is not None),4))
print('new best-of mean', round(st.mean(max(r[0] or 0,r[1]) for r in rows),4))
EOF
